let out;
const d = $json || {};
const exec = d.execution || {};
const err = exec.error || {};
const trig = d.trigger || {};
const terr = trig.error || {};
const wfName = (d.workflow && d.workflow.name) || 'unknown';
const wfId = (d.workflow && d.workflow.id) || '';
try {
  const node = (err.node && err.node.name) || exec.lastNodeExecuted || (terr.node && terr.node.name) || 'trigger';
  // Error text can carry secrets (a URL with a key in it, a token in a header). Mask them
  // before the text is logged or sent anywhere.
  const redact = (t) => String(t)
    .replace(/\b([a-z][a-z0-9+.-]*:\/\/)[^\s\/@:"']+:[^\s\/@"']+@/gi, '$1[redacted]@')
    .replace(/(https?:\/\/[^\s?#"']+)\?[^\s"']*/gi, '$1?[query removed]')
    .replace(/(hooks\.slack\.com\/services\/|api\.telegram\.org\/bot)[^\s"']+/gi, '$1[redacted]')
    .replace(/\b([Bb]earer|[Bb]asic|BEARER|BASIC)\s+(?=[A-Za-z0-9._~+\/=-]*(?:\d|[a-z][A-Z]))[A-Za-z0-9._~+\/=-]{8,}/g, '$1 [redacted]')   // a token, not the word after "basic" in a sentence
    .replace(/([A-Za-z0-9_-]*(?:api[_-]?key|token|secret(?:[_-]?(?:access[_-]?)?key)?|password|passwd|pwd|authorization))(["']?\s*[:=]\s*["']?)(?!bearer\b|basic\b)[^\s"',;&]+/gi, '$1$2[redacted]')
    .replace(/\S+/g, (tok) => /^https?:\/\//i.test(tok) || tok.includes('/') ? tok : tok.replace(/[A-Za-z0-9+_-]{40,}={0,2}/g, '[redacted]'));   // long runs, never inside a link or a file path
  const msg = redact(err.message || terr.message || 'Unknown error').slice(0, 1900);
  const errName = String(err.name || terr.name || '');
  const execId = String(exec.id || '');
  const execUrl = exec.url || '';
  const mode = exec.mode || trig.mode || '';
  const now = Date.now();

  // RULE TABLE, first match wins. Edit the four settings below for your estate.
  // 1. Workflows that are NOT production (test, demo, the fault injector): log only.
  const nonProd = /{NON_PRODUCTION_NAME_PATTERN}/i.test(wfName) || /Fault Injector/i.test(wfName);
  // 2. Messages that mean a record was lost or unconfirmed (your dead-letter alarm names).
  const p1Alarm = /{P1_ALARM_PATTERN}/i;
  // 3. Node names whose failure means a customer record was not written.
  const p1Nodes = [{P1_NODE_NAMES}];
  // 4. Workflows whose ANY failure is critical (for example client onboarding).
  const p1Workflows = /{P1_WORKFLOW_NAME_PATTERN}/i;
  const authFail = /unauthori[sz]ed|authori[sz]ation failed|check your credentials|invalid[_ ]?(token|grant|credential)|token (has )?expired|status code (401|403)\b/i;
  const httpCode = String(err.httpCode || terr.httpCode || '');   // n8n rewrites 401/403 messages, so check the code too
  // Dated mutes for KNOWN conditions. Each expires by itself; never add one without a date.
  const knownConditions = [
    // { messageContains: 'text that identifies the known condition', muteUntil: '2026-12-31T00:00:00Z', why: 'reason' }
  ];

  let tier = 'P2', reason = 'production failure (default)';
  const inj = msg.match(/FAULT-INJECTOR (P[123])/i);
  // The test override counts only when the failing workflow IS the fault injector. The name
  // comes from n8n, not from the error text, so an error message cannot lower its own tier.
  if (inj && /Fault Injector/i.test(wfName)) { tier = inj[1].toUpperCase(); reason = 'fault injector'; }
  else if (nonProd) { tier = 'P3'; reason = 'non-production workflow'; }
  else if (p1Alarm.test(msg) || p1Alarm.test(node)) { tier = 'P1'; reason = 'dead-letter alarm'; }
  else if (p1Nodes.includes(node)) { tier = 'P1'; reason = 'record write failed'; }
  else if (p1Workflows.test(wfName)) { tier = 'P1'; reason = 'critical workflow'; }
  else if (authFail.test(msg) || authFail.test(errName) || ['401', '403'].includes(httpCode)) { tier = 'P1'; reason = 'credential or auth failure'; }

  const mute = knownConditions.find(k => msg.includes(k.messageContains) && now < Date.parse(k.muteUntil));
  const windowHours = tier === 'P1' ? 1 : 6;
  const msgPrefix = msg.split(/\d{4}-\d{2}-\d{2}T/)[0].slice(0, 80).trim();
  out = { tier, reason, muted: !!mute, muteWhy: mute ? (mute.why + ', muted until ' + mute.muteUntil) : '', windowHours, msgPrefix, wfName, wfId, node, msg, errName, execId, execUrl, mode, when: new Date(now).toISOString(), since: new Date(now - windowHours * 3600 * 1000).toISOString(), classifyError: '' };
} catch (e) {
  const m = String((e && e.message) || e);
  out = { tier: 'P2', reason: 'classifier threw, defaulted to P2', muted: false, muteWhy: '', windowHours: 6, msgPrefix: ('Classify error: ' + m).slice(0, 80), wfName, wfId, node: (err.node && err.node.name) || exec.lastNodeExecuted || 'unknown', msg: 'Classify error: ' + m, errName: '', execId: String(exec.id || ''), execUrl: exec.url || '', mode: exec.mode || '', when: new Date().toISOString(), since: new Date(Date.now() - 6 * 3600 * 1000).toISOString(), classifyError: m };
}
return [{ json: out }];

const c = $('Classify').first().json;
const q = $json || {};
const queryOk = Array.isArray(q.results);
const repeat = queryOk && q.results.length > 0;
const repeatCheckFailed = !queryOk;
const title = (c.wfName + ' -> ' + c.node + (repeat ? ' (repeat)' : '') + (c.muted ? ' (muted)' : '')).slice(0, 2000);
const props = {
  'Error': { title: [{ text: { content: title } }] },
  'Workflow': { rich_text: [{ text: { content: c.wfName + ' (' + c.wfId + ')' } }] },
  'Node': { rich_text: [{ text: { content: c.node } }] },
  'Message': { rich_text: [{ text: { content: c.msg } }] },
  'Execution ID': { rich_text: [{ text: { content: c.execId } }] },
  'Status': { select: { name: 'New' } },
  'When': { date: { start: c.when } },
  'Severity': { select: { name: c.tier } }
};
const notify = c.tier !== 'P3' && !repeat && !c.muted;
if (!notify) props['Alerted'] = { select: { name: c.muted ? 'Muted' : (repeat ? 'Suppressed' : 'None') } };
return [{ json: { notionBody: { parent: { database_id: '{NOTION_ERROR_LOG_DATABASE_ID}' }, properties: props }, notify, email: notify && c.tier === 'P1', repeat, repeatCheckFailed } }];

const c = $('Classify').first().json;
const f = $('Format Error').first().json;
const w = $json || {};
const pageId = w.object === 'page' ? w.id : '';
const notionUrl = w.object === 'page' ? w.url : '';
const emoji = c.tier === 'P1' ? ':rotating_light:' : ':warning:';
const lines = [
  `${emoji} *${c.tier}* (${c.reason}): *${c.wfName}* failed at \`${c.node}\``,
  `Error: ${c.msg.slice(0, 500)}`,
  c.execUrl ? `Execution: ${c.execUrl}` : `Execution ID: ${c.execId || 'n/a'} (trigger-stage failure, no URL)`,
  notionUrl ? `Log row: ${notionUrl}` : 'Log row: WRITE FAILED, this message is the only record',
  f.repeatCheckFailed ? 'Repeat check unavailable (Notion query failed), sent unsuppressed' : '',
  c.classifyError ? `Classifier error: ${c.classifyError}` : '',
  c.tier === 'P1' ? '{P1_RECOVERY_LINE}' : ''
].filter(Boolean);
const text = lines.join('\n');
return [{ json: { notify: f.notify, email: f.email, tier: c.tier, pageId, notionUrl, slackText: text, emailSubject: `[${c.tier}] ${c.wfName} failed at ${c.node}`, emailBody: text.replace(/[*`]/g, '') } }];

const b = $('Build Alert').first().json;
if (!b.pageId) return [];
let slackOk = false, emailOk = false;
try { const s = $('Slack Alert').first().json; slackOk = !!(s && (s.ok === true || s.ts || s.message)); } catch (e) {}
try { const g = $('Gmail Alert').first().json; emailOk = !!(g && (g.id || g.threadId)); } catch (e) {}
const alerted = slackOk && emailOk ? 'Both' : slackOk ? 'Slack' : emailOk ? 'Email' : 'None';
return [{ json: { pageId: b.pageId, alerted, body: { properties: { 'Alerted': { select: { name: alerted } } } } } }];
